import 'dart:math' as math;
import 'package:flutter/material.dart';

enum GalaxyWorldKind { vegeta, game, identity, cinema, creation, music, family, archive, comingSoon }
class GalaxyWorld { final GalaxyWorldKind kind; final String title; final String description; const GalaxyWorld({required this.kind,required this.title,required this.description}); }
class DarkestWorldUniverse extends StatefulWidget { final List<GalaxyWorld> worlds; final ValueChanged<GalaxyWorld>? onWorldTap; const DarkestWorldUniverse({super.key,required this.worlds,this.onWorldTap}); @override State<DarkestWorldUniverse> createState()=>_DarkestWorldUniverseState(); }
class _DarkestWorldUniverseState extends State<DarkestWorldUniverse>{GalaxyWorldKind? selected;@override Widget build(BuildContext c){final compact=MediaQuery.sizeOf(c).width<700;final current=selected==null?null:widget.worlds.where((w)=>w.kind==selected).firstOrNull;return Scaffold(backgroundColor:const Color(0xFF010106),body:Stack(fit:StackFit.expand,children:[const _GalaxyBackground(),_GalaxyPlanets(worlds:widget.worlds,compact:compact,selected:selected,onSelect:(w)=>setState(()=>selected=selected==w.kind?null:w.kind)),Positioned(left:compact?18:34,top:compact?18:28,child:const Text('DARKESTWORLD',style:TextStyle(color:Colors.white,fontSize:14,letterSpacing:5,fontWeight:FontWeight.w300))),if(current!=null)Positioned(right:compact?14:34,bottom:compact?14:34,width:compact?260:340,child:_SelectionPanel(world:current,onClose:()=>setState(()=>selected=null),onEnter:()=>widget.onWorldTap?.call(current))) ]));}}
class _GalaxyBackground extends StatelessWidget{const _GalaxyBackground();@override Widget build(BuildContext c)=>CustomPaint(painter:_GalaxyBackgroundPainter());}
class _GalaxyBackgroundPainter extends CustomPainter{@override void paint(Canvas c,Size s){c.drawRect(Offset.zero&s,Paint()..shader=const RadialGradient(center:Alignment(0,-.15),radius:1.1,colors:[Color(0xFF17152A),Color(0xFF060710),Color(0xFF010105)]).createShader(Offset.zero&s));final r=math.Random(17);for(var i=0;i<190;i++)c.drawCircle(Offset(r.nextDouble()*s.width,r.nextDouble()*s.height),.25+r.nextDouble()*.85,Paint()..color=Colors.white.withValues(alpha:.16+r.nextDouble()*.20));}@override bool shouldRepaint(covariant _GalaxyBackgroundPainter old)=>false;}
class _GalaxyPlanets extends StatelessWidget{final List<GalaxyWorld> worlds;final bool compact;final GalaxyWorldKind? selected;final ValueChanged<GalaxyWorld> onSelect;const _GalaxyPlanets({required this.worlds,required this.compact,required this.selected,required this.onSelect});static const pos=<GalaxyWorldKind,Offset>{GalaxyWorldKind.vegeta:Offset(.50,.53),GalaxyWorldKind.game:Offset(.77,.25),GalaxyWorldKind.identity:Offset(.20,.34),GalaxyWorldKind.cinema:Offset(.84,.59),GalaxyWorldKind.creation:Offset(.22,.73),GalaxyWorldKind.music:Offset(.61,.81),GalaxyWorldKind.family:Offset(.39,.17),GalaxyWorldKind.archive:Offset(.09,.56),GalaxyWorldKind.comingSoon:Offset(.91,.80)};static const fac=<GalaxyWorldKind,double>{GalaxyWorldKind.vegeta:.30,GalaxyWorldKind.game:.16,GalaxyWorldKind.identity:.145,GalaxyWorldKind.cinema:.135,GalaxyWorldKind.creation:.13,GalaxyWorldKind.music:.115,GalaxyWorldKind.family:.105,GalaxyWorldKind.archive:.075,GalaxyWorldKind.comingSoon:.065};@override Widget build(BuildContext c){final s=MediaQuery.sizeOf(c);final b=math.min(s.width,s.height);return Stack(fit:StackFit.expand,children:[for(final w in worlds.where((w)=>pos.containsKey(w.kind)))Positioned(left:s.width*pos[w.kind]!.dx,top:s.height*pos[w.kind]!.dy,child:Transform.translate(offset:Offset(-_size(b,w.kind)/2,-_size(b,w.kind)/2),child:_Planet(world:w,size:_size(b,w.kind),muted:selected!=null&&selected!=w.kind,onTap:()=>onSelect(w))))]);}double _size(double b,GalaxyWorldKind k)=>math.max(64,b*(fac[k]??.1));}
class _Planet extends StatelessWidget{final GalaxyWorld world;final double size;final bool muted;final VoidCallback onTap;const _Planet({required this.world,required this.size,required this.muted,required this.onTap});@override Widget build(BuildContext c)=>GestureDetector(onTap:onTap,child:Opacity(opacity:muted ? .30 : 1,child:SizedBox(width:size,child:Column(mainAxisSize:MainAxisSize.min,children:[SizedBox(width:size,height:size,child:CustomPaint(painter:_WorldPlanetPainter(seed:world.kind.index+21,accent:world.kind==GalaxyWorldKind.vegeta?const Color(0xFF8A6BB2):const Color(0xFF6173A0)))),const SizedBox(height:7),Text(world.title,maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(color:Colors.white.withValues(alpha:.86),fontSize:world.kind==GalaxyWorldKind.vegeta?11:8,letterSpacing:world.kind==GalaxyWorldKind.vegeta?3:1.7))]))));}
class _WorldPlanetPainter extends CustomPainter{final int seed;final Color accent;const _WorldPlanetPainter({required this.seed,required this.accent});@override void paint(Canvas c,Size s){final o=Offset(s.width/2,s.height/2),r=s.shortestSide*.46,rect=Rect.fromCircle(center:o,radius:r);c.drawCircle(o,r*1.13,Paint()..shader=RadialGradient(colors:[accent.withValues(alpha:.28),Colors.transparent]).createShader(Rect.fromCircle(center:o,radius:r*1.13)));c.drawCircle(o,r,Paint()..shader=const RadialGradient(center:Alignment(-.36,-.42),radius:1.08,colors:[Color(0xFF7182A4),Color(0xFF2B3851),Color(0xFF080C17)]).createShader(rect));c.save();c.clipPath(Path()..addOval(rect));final q=math.Random(seed);for(var i=0;i<14;i++){final p=Offset(o.dx+(q.nextDouble()*2-1)*r*.7,o.dy+(q.nextDouble()*2-1)*r*.62);c.drawOval(Rect.fromCenter(center:p,width:r*(.22+q.nextDouble()*.48),height:r*(.06+q.nextDouble()*.18)),Paint()..color=accent.withValues(alpha:.055+q.nextDouble()*.075));}c.restore();c.drawCircle(o+Offset(r*.38,r*.08),r*.8,Paint()..shader=RadialGradient(colors:[Colors.transparent,Colors.black.withValues(alpha:.48)]).createShader(Rect.fromCircle(center:o+Offset(r*.38,r*.08),radius:r*.8)));c.drawArc(Rect.fromCircle(center:o,radius:r*1.015),math.pi*.68,math.pi*.72,false,Paint()..style=PaintingStyle.stroke..strokeWidth=1.2..color=Colors.white.withValues(alpha:.20));}@override bool shouldRepaint(covariant _WorldPlanetPainter old)=>false;}
class _SelectionPanel extends StatelessWidget{final GalaxyWorld world;final VoidCallback onClose,onEnter;const _SelectionPanel({required this.world,required this.onClose,required this.onEnter});@override Widget build(BuildContext c)=>Material(color:Colors.transparent,child:Container(padding:const EdgeInsets.all(18),decoration:BoxDecoration(color:const Color(0xE6090914),border:Border.all(color:Colors.white.withValues(alpha:.12)),borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,mainAxisSize:MainAxisSize.min,children:[Text(world.title,style:const TextStyle(color:Colors.white,fontSize:16,letterSpacing:2)),const SizedBox(height:8),Text(world.description,style:TextStyle(color:Colors.white.withValues(alpha:.68))),const SizedBox(height:14),Row(children:[TextButton(onPressed:onClose,child:const Text('Sluiten')),const Spacer(),ElevatedButton(onPressed:onEnter,child:const Text('Openen'))])])));}
